CREATE TABLE "DocumentFrontMatter" (
	id SERIAL NOT NULL,
	title TEXT NOT NULL,
	lang TEXT,
	normative BOOLEAN NOT NULL,
	audience "DataScope" NOT NULL,
	retrieval "DocumentRetrieval",
	status TEXT,
	verified_at DATE,
	stale_after TEXT,
	enforced_by TEXT,
	last_updated DATE,
	PRIMARY KEY (id)
);
CREATE INDEX "ix_DocumentFrontMatter_id" ON "DocumentFrontMatter" (id);
COMMENT ON TABLE "DocumentFrontMatter" IS 'Metadata every governed Markdown document declares, so a retriever can carry a passage''s authority and audience along with its text. An ungoverned RAG loses both at chunk time: explanatory prose comes back looking like a rule, and a Realm-private paragraph comes back to whoever asked. Those are the documentary forms of privilege escalation, and this schema is where they are refused (ADR-0014).';
COMMENT ON COLUMN "DocumentFrontMatter".lang IS 'ISO 639-1 code of the document''s prose. Defaults to English; a non-normative document may declare fr for explanatory text (docs/concepts/positionnement-conceptuel.md).';
COMMENT ON COLUMN "DocumentFrontMatter".normative IS 'Whether this document states rules. Travels with every chunk: a retriever may quote a false document as explanation and never as authority (ADR-0005 applied to retrieval).';
COMMENT ON COLUMN "DocumentFrontMatter".audience IS 'Widest scope a retrieval may serve this document to. Required with no default, because a default here would silently publish.';
COMMENT ON COLUMN "DocumentFrontMatter".enforced_by IS 'Comma-separated paths that mechanically enforce this document''s rules. Checked for existence by scripts/check-corpus-budget.py.';

