	subdomain TEXT NOT NULL,
	"baseDomain" TEXT NOT NULL,
	PRIMARY KEY (id)
);
CREATE INDEX "ix_RealmIngressBinding_id" ON "RealmIngressBinding" (id);
COMMENT ON TABLE "RealmIngressBinding" IS 'Per-tenant DNS routing for one RealmTemplate. `baseDomain` is deliberately not named `canonicalDomain` or `hostname`: OfferingTopology.canonicalDomain and OfferingTopology.hostname (this same module) already use both names for an inclusion flag, not a domain value -- a third reuse of either name for a different shape would recreate the exact collision the `ProjectionSource`/`ProjectionSpec` naming warns against elsewhere in this metamodel. Deliberately carries no audience, policy, capability or other authority-bearing attribute: Rego refusing two RealmTemplates the same hostname protects routing correctness, not authorization -- that stays on RealmEnforcement.';
COMMENT ON COLUMN "RealmIngressBinding".subdomain IS 'DNS label distinguishing this Realm''s hostname under baseDomain.';
COMMENT ON COLUMN "RealmIngressBinding"."baseDomain" IS 'The parent domain subdomain is bound under, e.g. jumo.dev or a client-owned domain.';

CREATE TABLE "RealmEnforcement" (
	id SERIAL NOT NULL,
	"branchProtection" "BranchProtectionState" NOT NULL,
	"observedAt" TIMESTAMP WITHOUT TIME ZONE,
	"evidenceRef" TEXT,
	"evidenceMaxAge" TEXT,
	"independentVerification" "IndependentVerificationState",
	"independentVerificationObservedAt" TIMESTAMP WITHOUT TIME ZONE,
	"independentVerificationEvidenceRef" TEXT,
	"independentVerificationEvidenceMaxAge" TEXT,
	PRIMARY KEY (id)
);
CREATE INDEX "ix_RealmEnforcement_id" ON "RealmEnforcement" (id);
COMMENT ON TABLE "RealmEnforcement" IS 'ENFORCED requiring observedAt/evidenceRef/evidenceMaxAge moves to Rego: claiming enforcement costs an observation and a reference to it.';
COMMENT ON COLUMN "RealmEnforcement"."evidenceMaxAge" IS 'Maximum age of the Forge protection observation before an autonomy gate must treat the claim as stale (ADR-0028, default PT24H).';
COMMENT ON COLUMN "RealmEnforcement"."independentVerification" IS 'Optional, additive claim distinct from branchProtection. Not wired into whether the corpus.independence.* rules apply -- those keep running unconditionally regardless of this field. Only claiming ENFORCED here has any effect: it must then carry its own fresh independentVerificationObservedAt/independentVerificationEvidenceRef within independentVerificationEvidenceMaxAge (Rego), same evidence-costs-a-claim shape as branchProtection.';
COMMENT ON COLUMN "RealmEnforcement"."independentVerificationEvidenceMaxAge" IS 'Maximum age of the independent-verification observation before its ENFORCED claim must be treated as stale, default PT24H.';

