	transport TEXT NOT NULL,
	"upstreamKind" TEXT,
	placement "McpBundlePlacement" NOT NULL,
	entrypoint TEXT,
	PRIMARY KEY (id)
);
CREATE INDEX "ix_McpBundleRuntime_id" ON "McpBundleRuntime" (id);
COMMENT ON TABLE "McpBundleRuntime" IS 'An McpBundle''s single upstream branch is always OCI_STDIO with a pinned artifact (McpBundleSpec.artifact); the STREAMABLE_HTTP branch has no bundle and is reached only through ConnectorDefinitionSpec.remoteMcpServiceRef and RemoteMcpServiceSpec.transport MCP_STREAMABLE_HTTP (ADR-0050 decisions 6-7).';
COMMENT ON COLUMN "McpBundleRuntime"."upstreamKind" IS 'Not schema-required -- the pinned jumo-core sibling source only gains this field at its own pace; enforced unconditionally in Rego instead (corpus.bundle.upstream-kind-required), which reads the live composed corpus rather than a stale lock.';
COMMENT ON COLUMN "McpBundleRuntime".placement IS 'v2 admits only EXECUTION_CELL; CLIENT_CELL and REMOTE remain declarable at the schema level but are refused by corpus.bundle.execution-cell-only-placement (Rego, not schema) for the same reason.';

