COMMENT ON COLUMN "ProviderAccountSpec".provider IS 'Vendor and access path, such as anthropic-cli or openai-api. Two accounts on the same vendor are not independent of each other.';
COMMENT ON COLUMN "ProviderAccountSpec"."independenceGroup" IS 'Accounts sharing a group are not independent. Falling back within the same group would let one account both produce and verify (docs/concepts/positionnement-conceptuel.md#diversite-des-pannes) -- a declared separation, not a proof of independence; a fault-diversity vector (provider, model, prompt, sources, tools, framing) would be the finer-grained signal, not yet modeled as its own field. Inherited from the referenced ProviderPlatform''s independenceGroup when absent.';
COMMENT ON COLUMN "ProviderAccountSpec"."secretBindingRef_uid" IS 'The sole OpenBao binding that may hold this named account''s credential; the value is never contractual state.';

CREATE TABLE "ProviderRouting" (
	id SERIAL NOT NULL,
	priority INTEGER,
	mode "AccessMode" NOT NULL,
	"gatewayRef" TEXT,
	"upstreamHost" TEXT,
	"platformRef_uid" INTEGER,
	PRIMARY KEY (id)
);
CREATE INDEX "ix_ProviderRouting_id" ON "ProviderRouting" (id);
COMMENT ON TABLE "ProviderRouting" IS 'None';
COMMENT ON COLUMN "ProviderRouting".priority IS 'Deterministic account selection order for a compatible worker requirement profile. Lower values are selected first.';
COMMENT ON COLUMN "ProviderRouting"."gatewayRef" IS 'Required when mode is GATEWAY_ROUTED; forbidden when PLAN_DIRECT (Rego).';
COMMENT ON COLUMN "ProviderRouting"."upstreamHost" IS 'Required exactly when the referenced ProviderPlatform declares hostDeclaredByAccount true (a generic platform such as an OpenAI-compatible aggregator); forbidden otherwise (Rego).';
COMMENT ON COLUMN "ProviderRouting"."platformRef_uid" IS 'The ProviderPlatform catalog entry this account was opened against. Required when mode is GATEWAY_ROUTED; forbidden when PLAN_DIRECT, which has no upstream provider-egress traffic (Rego).';

CREATE TABLE "ProviderPlatformSpec" (
	id SERIAL NOT NULL,
	"wireProtocol" "WireProtocol" NOT NULL,
	"egressRouteId" TEXT NOT NULL,
	"upstreamHost" TEXT,
	"completionPath" TEXT NOT NULL,
	"modelCatalogPath" TEXT NOT NULL,
	"credentialHeader" "CredentialHeaderStyle" NOT NULL,
	"independenceGroup" TEXT NOT NULL,
	"hostDeclaredByAccount" BOOLEAN NOT NULL,
	PRIMARY KEY (id)
);
CREATE INDEX "ix_ProviderPlatformSpec_id" ON "ProviderPlatformSpec" (id);
COMMENT ON TABLE "ProviderPlatformSpec" IS 'None';
COMMENT ON COLUMN "ProviderPlatformSpec"."egressRouteId" IS 'Names the generated provider-egress nginx location this platform''s traffic proxies through. Never a raw URL; the worker builds only /{egressRouteId}/... and cannot select an upstream itself.';
COMMENT ON COLUMN "ProviderPlatformSpec"."upstreamHost" IS 'Fixed TLS upstream for an integrated platform. Forbidden when hostDeclaredByAccount is true (Rego); a generic platform''s host is named per-account instead.';
COMMENT ON COLUMN "ProviderPlatformSpec"."independenceGroup" IS 'Default independenceGroup for an account opened against this platform when the account does not declare its own.';
COMMENT ON COLUMN "ProviderPlatformSpec"."hostDeclaredByAccount" IS 'True only for a generic platform (e.g. an OpenAI-compatible aggregator such as OpenRouter) whose upstream host is named per-account instead of fixed by this catalog entry.';

CREATE TABLE "ProviderNativeEffort" (
