CREATE INDEX "ix_ProviderNativeEffort_id" ON "ProviderNativeEffort" (id);
COMMENT ON TABLE "ProviderNativeEffort" IS 'Provider-native reasoning-effort parameters, applied verbatim by RequestShape for the rung''s protocol -- OpenAI reasoning_effort, Anthropic thinking budget and max_tokens, Google thinkingConfig.';
COMMENT ON COLUMN "ProviderNativeEffort"."reasoningEffort" IS 'Provider-native effort token passed through verbatim (e.g. OpenAI''s ''medium'' or ''high'').';
COMMENT ON COLUMN "ProviderNativeEffort"."thinkingBudgetTokens" IS 'Native thinking-token budget for a protocol that exposes one (Anthropic extended thinking, Google thinkingConfig).';

