COMMENT ON TABLE "ChangeSetProposal" IS 'Ordered multi-file changeset proposed against one repository, the unit ForgeApplier opens as one repository PR within a multi-repository saga (multi-repository-change-set-saga AC1). Owner approval and phase progression are tracked separately, not on this shape.';

CREATE TABLE "ChangeSetProjection" (
	id SERIAL NOT NULL,
	"changeSetProposalId" TEXT NOT NULL,
	"realmId" TEXT NOT NULL,
	provider TEXT NOT NULL,
