COMMENT ON TABLE "ImprovementLoopSpec" IS 'None';
COMMENT ON COLUMN "ImprovementLoopSpec"."projectRef_uid" IS 'One loop never reaches across Projects; that would be a delegation, not a rhythm.';
COMMENT ON COLUMN "ImprovementLoopSpec"."assessmentProcessSpecRef_uid" IS 'Optional explicit ProcessSpec (execution.yaml).';

