COMMENT ON TABLE "AttentionItemSpec" IS 'None';
COMMENT ON COLUMN "AttentionItemSpec".classification IS 'Same enumeration as capability data access, retrieval and rendering (canonical decision 98).';
COMMENT ON COLUMN "AttentionItemSpec".confidence IS 'Confidence of the interpretation behind this item, not of the outcome it reports.';
COMMENT ON COLUMN "AttentionItemSpec"."admissionReason" IS 'Required on ADMISSION_REFUSED (Rego).';

