CREATE TABLE "PrincipleSet" (
	id SERIAL NOT NULL,
	"apiVersion" TEXT NOT NULL,
	kind TEXT NOT NULL,
	metadata_uid INTEGER NOT NULL,
	spec_id INTEGER NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(metadata_uid) REFERENCES "Metadata" (uid),
	FOREIGN KEY(spec_id) REFERENCES "PrincipleSetSpec" (id)
);
CREATE INDEX "ix_PrincipleSet_id" ON "PrincipleSet" (id);
COMMENT ON TABLE "PrincipleSet" IS 'Judgement heuristics. Principles influence prioritization, communication and judgement; they never grant capabilities (ADR-0005). The authority field is constrained to INFLUENCE_ONLY so this cannot drift.';

CREATE TABLE "Project" (
	id SERIAL NOT NULL,
	"apiVersion" TEXT NOT NULL,
	kind TEXT NOT NULL,
	metadata_uid INTEGER NOT NULL,
	spec_id INTEGER NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(metadata_uid) REFERENCES "Metadata" (uid),
	FOREIGN KEY(spec_id) REFERENCES "ProjectSpec" (id)
);
CREATE INDEX "ix_Project_id" ON "Project" (id);
COMMENT ON TABLE "Project" IS 'A governed body of work declared in a Realm control repository. Git repositories are optional bound resources, not the identity of a Project.';

CREATE TABLE "Milestone" (
	uid SERIAL NOT NULL,
	id TEXT NOT NULL,
	"order" INTEGER NOT NULL,
	"exitCondition" TEXT NOT NULL,
	"ProjectSpec_id" INTEGER,
