	FOREIGN KEY("ProjectSpec_id") REFERENCES "ProjectSpec" (id)
);
CREATE INDEX "ix_Milestone_uid" ON "Milestone" (uid);
COMMENT ON TABLE "Milestone" IS 'None';
COMMENT ON COLUMN "Milestone"."order" IS 'Delivery order. Breaks ties when two milestones would otherwise sort ambiguously; the generated roadmap groups in this order, not declaration order.';
COMMENT ON COLUMN "Milestone"."ProjectSpec_id" IS 'Autocreated FK slot';

CREATE TABLE "RepositoryBinding" (
	uid SERIAL NOT NULL,
