	provider "ForgeProvider" NOT NULL,
	repository TEXT NOT NULL,
	"approvalPolicy" "SharedRepositoryApprovalPolicy",
	"ProjectSpec_id" INTEGER,
	PRIMARY KEY (uid),
	FOREIGN KEY("ProjectSpec_id") REFERENCES "ProjectSpec" (id)
);
CREATE INDEX "ix_RepositoryBinding_uid" ON "RepositoryBinding" (uid);
COMMENT ON TABLE "RepositoryBinding" IS 'None';
COMMENT ON COLUMN "RepositoryBinding".repository IS 'owner/name. A literal TODO is rejected (Rego, for the placeholder scan).';
COMMENT ON COLUMN "RepositoryBinding"."approvalPolicy" IS 'OWNER_ONLY (default): only the ownerRealm may authorize forge writes. MUTUAL_CONSENT: every co-owner Realm must signal approval before ForgeApplier merges.';
COMMENT ON COLUMN "RepositoryBinding"."ProjectSpec_id" IS 'Autocreated FK slot';

CREATE TABLE "ProjectPersonalSpaceBinding" (
	id SERIAL NOT NULL,
	"ProjectSpec_id" INTEGER,
