	FOREIGN KEY("personalSpaceRef_uid") REFERENCES "ContractReference" (uid)
);
CREATE INDEX "ix_ProjectPersonalSpaceBinding_id" ON "ProjectPersonalSpaceBinding" (id);
COMMENT ON TABLE "ProjectPersonalSpaceBinding" IS 'None';
COMMENT ON COLUMN "ProjectPersonalSpaceBinding"."ProjectSpec_id" IS 'Autocreated FK slot';

CREATE TABLE "RealmTemplate" (
	id SERIAL NOT NULL,
	"apiVersion" TEXT NOT NULL,
	kind TEXT NOT NULL,
	metadata_uid INTEGER NOT NULL,
	spec_id INTEGER NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(metadata_uid) REFERENCES "Metadata" (uid),
	FOREIGN KEY(spec_id) REFERENCES "RealmTemplateSpec" (id)
);
CREATE INDEX "ix_RealmTemplate_id" ON "RealmTemplate" (id);
COMMENT ON TABLE "RealmTemplate" IS 'A Realm is a governance, privacy and security boundary. Spheres group work inside a Realm without being security boundaries (canonical decision 12). `ingress` is the same shape one level up, for DNS instead of workspace grouping: `RealmIngressBinding` carries no audience, policy, capability or other authority-bearing attribute, so a subdomain stays routing only by construction, never a security boundary -- `enforcement` on this same spec remains the only field that is.';

CREATE TABLE "JumoKit" (
