CREATE INDEX "ix_JumoKit_id" ON "JumoKit" (id);
COMMENT ON TABLE "JumoKit" IS 'Root manifest for one portable Jumo Kit repository. Official schemas are supplied by Jumo, never by the kit repository. An active contract kind: the manifest a kit repository itself declares.';

