COMMENT ON TABLE "RenderedKitAsset" IS 'Provenance for one rendered binary asset or i18n bundle -- same digest-provenance shape as RenderedKitFile, kept a separate class because the source/target patterns admit assetExports'' file types instead of `.yml`.';
COMMENT ON COLUMN "RenderedKitAsset"."KitLockSpec_id" IS 'Autocreated FK slot';

CREATE TABLE "KitReleaseCertification" (
	id SERIAL NOT NULL,
	"apiVersion" TEXT NOT NULL,
	kind TEXT NOT NULL,
	metadata_uid INTEGER NOT NULL,
	spec_id INTEGER NOT NULL,
