);
CREATE INDEX "ix_KitReleaseCertification_id" ON "KitReleaseCertification" (id);
COMMENT ON TABLE "KitReleaseCertification" IS 'Portable independent review of an exact Jumo Kit release and its executable modules or connector artifacts. signedBy != verifiedBy (source schema''s $data cross-field check) moves to Rego -- no actor certifies its own release.';

CREATE TABLE "OfferingSpecBody" (
