	FOREIGN KEY(validation_id) REFERENCES "OfferingValidation" (id)
);
CREATE INDEX "ix_OfferingSpecBody_id" ON "OfferingSpecBody" (id);
COMMENT ON TABLE "OfferingSpecBody" IS 'None';

CREATE TABLE "RoleDefinition" (
	id SERIAL NOT NULL,
