	FOREIGN KEY(spec_id) REFERENCES "RoleDefinitionSpec" (id)
);
CREATE INDEX "ix_RoleDefinition_id" ON "RoleDefinition" (id);
COMMENT ON TABLE "RoleDefinition" IS 'A stable Realm-owned acting role carrying a mission. Its bearer is declared separately by RoleAssignment; neither declaration grants authority. Renamed from Operator.';

CREATE TABLE "AgentDefinition" (
