	FOREIGN KEY(spec_id) REFERENCES "AgentDefinitionSpec" (id)
);
CREATE INDEX "ix_AgentDefinition_id" ON "AgentDefinition" (id);
COMMENT ON TABLE "AgentDefinition" IS 'Reusable, portable agent behavior. Requests capabilities; never grants them. Renamed from AgentArchetype.';

CREATE TABLE "RoleAssignmentSpec" (
