	FOREIGN KEY(bearer_id) REFERENCES "RoleBearer" (id)
);
CREATE INDEX "ix_RoleAssignmentSpec_id" ON "RoleAssignmentSpec" (id);
COMMENT ON TABLE "RoleAssignmentSpec" IS 'None';

CREATE TABLE "TeamSpecBody" (
	id SERIAL NOT NULL,
	"ownerRealm" TEXT NOT NULL,
	purpose TEXT NOT NULL,
	"roleKey" TEXT,
	coordination_id INTEGER NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(coordination_id) REFERENCES "TeamCoordination" (id)
);
CREATE INDEX "ix_TeamSpecBody_id" ON "TeamSpecBody" (id);
COMMENT ON TABLE "TeamSpecBody" IS 'None';
COMMENT ON COLUMN "TeamSpecBody".coordination_id IS 'The managed dependency, not the team, is the unit of analysis (docs/concepts/positionnement-conceptuel.md#coordination-des-dependances). The source schema forced one `mode` for the whole team; this carries one or more CoordinationMechanismBinding entries instead, each scoped to the dependency it governs.';

CREATE TABLE "CoordinationMechanismBinding" (
	id SERIAL NOT NULL,
	mechanism "CoordinationMechanism" NOT NULL,
	"dependencyKind" TEXT,
	phase TEXT,
	"riskTier" TEXT,
	"TeamCoordination_id" INTEGER,
	"CoordinationProfileSpec_id" INTEGER,
	PRIMARY KEY (id),
	FOREIGN KEY("TeamCoordination_id") REFERENCES "TeamCoordination" (id),
	FOREIGN KEY("CoordinationProfileSpec_id") REFERENCES "CoordinationProfileSpec" (id)
);
CREATE INDEX "ix_CoordinationMechanismBinding_id" ON "CoordinationMechanismBinding" (id);
COMMENT ON TABLE "CoordinationMechanismBinding" IS 'One coordination mechanism scoped to the dependency it actually governs, replacing a single team-wide mode (docs/concepts/positionnement-conceptuel.md#coordination-des-dependances). Shared by TeamSpec and CoordinationProfile so a team''s inline coordination and a reusable named profile speak the same vocabulary.';
COMMENT ON COLUMN "CoordinationMechanismBinding"."dependencyKind" IS 'Open vocabulary naming the managed dependency (e.g. resource-sharing, prerequisite, simultaneity, decomposition -- Malone & Crowston''s categories). Not an enum: the catalog of dependency kinds is expected to grow with experience, and closing it here would recreate the single-mode rigidity this redesign removes.';
COMMENT ON COLUMN "CoordinationMechanismBinding".phase IS 'Open vocabulary naming the work phase this binding applies to.';
COMMENT ON COLUMN "CoordinationMechanismBinding"."riskTier" IS 'Open vocabulary; aligns with ActionCapabilitySet''s riskTier where relevant.';
COMMENT ON COLUMN "CoordinationMechanismBinding"."TeamCoordination_id" IS 'Autocreated FK slot';
COMMENT ON COLUMN "CoordinationMechanismBinding"."CoordinationProfileSpec_id" IS 'Autocreated FK slot';

CREATE TABLE "CoordinationProfile" (
	id SERIAL NOT NULL,
	"apiVersion" TEXT NOT NULL,
	kind TEXT NOT NULL,
	metadata_uid INTEGER NOT NULL,
	spec_id INTEGER NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(metadata_uid) REFERENCES "Metadata" (uid),
	FOREIGN KEY(spec_id) REFERENCES "CoordinationProfileSpec" (id)
);
CREATE INDEX "ix_CoordinationProfile_id" ON "CoordinationProfile" (id);
COMMENT ON TABLE "CoordinationProfile" IS 'A named, reusable coordination profile: authorized mechanisms, target dependencies, rhythm, and preconditions for team coordination. Distinct from TeamSpec.coordination (inline, per-team) -- a CoordinationProfile is declared once and referenced by name from multiple teams or improvement-loop targets, while TeamSpec.coordination is that team''s own binding. Already used mechanisms[] in the source schema (unlike TeamSpec''s single `mode`), so this class''s mechanisms list was not itself the redesign target -- it gains the same CoordinationMechanismBinding shape as TeamSpec for vocabulary consistency, replacing what was a flat CoordinationMechanism list.';

CREATE TABLE "RoutingEligibility" (
