);
CREATE INDEX "ix_AdvisorProfile_id" ON "AdvisorProfile" (id);
COMMENT ON TABLE "AdvisorProfile" IS 'A stable role''s declared, contextual ways of being solicited. It selects no authority and never duplicates the Chief of Staff identity.';

