CREATE TABLE "OrganizationSpec" (
	id SERIAL NOT NULL,
	"apiVersion" TEXT NOT NULL,
	kind TEXT NOT NULL,
	metadata_uid INTEGER NOT NULL,
	spec_id INTEGER NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(metadata_uid) REFERENCES "Metadata" (uid),
	FOREIGN KEY(spec_id) REFERENCES "OrganizationSpecBody" (id)
);
CREATE INDEX "ix_OrganizationSpec_id" ON "OrganizationSpec" (id);
COMMENT ON TABLE "OrganizationSpec" IS 'A named organization of roles for a recurring mission (docs/concepts/positionnement-conceptuel.md#organisation-moise), referencing RoleDefinition, TeamSpec, RoleAssignment, and OrganizationTemplate without replacing or absorbing any of them -- those classes stay independently declarable, which is what "renamed without absorption" means at the composite-class boundary too. The software-delivery example: a chief-of-staff role, an implementer, a reviewer, a human owner, plus incompatibility and independence constraints between them.';

CREATE TABLE "OrganizationRoleBinding" (
