CREATE INDEX "ix_OrganizationRoleBinding_id" ON "OrganizationRoleBinding" (id);
COMMENT ON TABLE "OrganizationRoleBinding" IS 'None';
COMMENT ON COLUMN "OrganizationRoleBinding"."seatId" IS 'A named seat in this organization, e.g. "chief-of-staff", "implementer", "reviewer", "owner".';
COMMENT ON COLUMN "OrganizationRoleBinding"."humanSeat" IS 'True for the human-owner seat, which is never filled by an AgentDefinition bearer.';
