	FOREIGN KEY(spec_id) REFERENCES "ControlCatalogSpec" (id)
);
CREATE INDEX "ix_ControlCatalog_id" ON "ControlCatalog" (id);
COMMENT ON TABLE "ControlCatalog" IS 'Internal controls, reusable across ComplianceProfiles (docs/concepts/positionnement-conceptuel.md#conformite-et-auditabilite-par-construction). Split out of the source GovernanceOverlay''s inline `controls[]` array, so a control is declared once and mapped from many profiles rather than copy-pasted per referential.';

CREATE TABLE "ComplianceProfile" (
	id SERIAL NOT NULL,
	"apiVersion" TEXT NOT NULL,
	kind TEXT NOT NULL,
	metadata_uid INTEGER NOT NULL,
	spec_id INTEGER NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(metadata_uid) REFERENCES "Metadata" (uid),
	FOREIGN KEY(spec_id) REFERENCES "ComplianceProfileSpec" (id)
);
CREATE INDEX "ix_ComplianceProfile_id" ON "ComplianceProfile" (id);
COMMENT ON TABLE "ComplianceProfile" IS 'A named referential (edition, official URI) and its mappings to a ControlCatalog (docs/concepts/positionnement-conceptuel.md#conformite-et-auditabilite-par-construction). Split out of GovernanceOverlay. Never recopies referential text -- identifiers, edition, and URI only. Carries the RGPD art. 30 processing register: a compliance profile scoped to data protection references the processing activities it covers, rather than inventing a separate kind for a register most Realms will attach to exactly one profile.';

CREATE TABLE "ComplianceMapping" (
	id SERIAL NOT NULL,
	"controlRef" TEXT NOT NULL,
	"referentialArticle" TEXT,
