);
CREATE INDEX "ix_ComplianceMapping_id" ON "ComplianceMapping" (id);
COMMENT ON TABLE "ComplianceMapping" IS 'Example mappings are marked DRAFT; no MAPPED or EVIDENCED status may be displayed as a certification claim (enforced in Rego, not here).';
COMMENT ON COLUMN "ComplianceMapping"."controlRef" IS 'References a Control.controlId in the linked ControlCatalog.';
COMMENT ON COLUMN "ComplianceMapping"."referentialArticle" IS 'e.g. an AI Act article number, an ISO clause number.';
COMMENT ON COLUMN "ComplianceMapping"."ComplianceProfileSpec_id" IS 'Autocreated FK slot';

CREATE TABLE "ProcessingRegisterEntry" (
