COMMENT ON TABLE "ProcessingRegisterEntry" IS 'RGPD art. 30 register entry.';
COMMENT ON COLUMN "ProcessingRegisterEntry"."ComplianceProfileSpec_id" IS 'Autocreated FK slot';
COMMENT ON COLUMN "ProcessingRegisterEntry"."dpiaEvidenceProfileRef_uid" IS 'References an EvidenceProfile carrying the DPIA (art. 35), when required.';

CREATE TABLE "EvidenceProfile" (
	id SERIAL NOT NULL,
	"apiVersion" TEXT NOT NULL,
	kind TEXT NOT NULL,
	metadata_uid INTEGER NOT NULL,
	spec_id INTEGER NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(metadata_uid) REFERENCES "Metadata" (uid),
