);
CREATE INDEX "ix_EvidenceProfile_id" ON "EvidenceProfile" (id);
COMMENT ON TABLE "EvidenceProfile" IS 'The type, source, freshness, independence, and retention an assessment''s evidence must meet. Split out of GovernanceOverlay. Carries the DPIA (RGPD art. 35) alongside the pre-existing evidence-quality fields -- an impact assessment is itself a form of evidence about the system, not a separate concept.';

CREATE TABLE "ProcessSpec" (
	id SERIAL NOT NULL,
	"apiVersion" TEXT NOT NULL,
	kind TEXT NOT NULL,
	metadata_uid INTEGER NOT NULL,
	spec_id INTEGER NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(metadata_uid) REFERENCES "Metadata" (uid),
	FOREIGN KEY(spec_id) REFERENCES "ProcessSpecBody" (id)
);
CREATE INDEX "ix_ProcessSpec_id" ON "ProcessSpec" (id);
COMMENT ON TABLE "ProcessSpec" IS 'A durable process: a graph of typed steps and flows, compiled to a Temporal Workflow and projected to BPMN 2.0 XML for audit and rendering. A Temporal Workflow normally corresponds to an Episode (canonical decision 39, unchanged by this redesign).';

CREATE TABLE "ProcessStep" (
	uid SERIAL NOT NULL,
	id TEXT NOT NULL,
	kind "ProcessStepKind" NOT NULL,
	"semanticStage" "ProcessStepSemanticStage",
	"capabilityRef" TEXT,
	ring "Ring",
	"idempotencyKey" TEXT,
	"opaEntrypoint" TEXT,
	"terminalState" "ProcessTerminalState",
	"signalType" TEXT,
	"gatewayMode" "ProcessGatewayMode",
	"gatewayRole" "ProcessGatewayRole",
	"pairedGatewayRef" TEXT,
	"loopMaximum" INTEGER,
	"fallbackFlowRef" TEXT,
	"compensationForStepRef" TEXT,
	"ProcessSpecBody_id" INTEGER,
	"subprocessReleaseRef_uid" INTEGER,
	PRIMARY KEY (uid),
	FOREIGN KEY("ProcessSpecBody_id") REFERENCES "ProcessSpecBody" (id),
	FOREIGN KEY("subprocessReleaseRef_uid") REFERENCES "ContractReference" (uid)
);
CREATE INDEX "ix_ProcessStep_uid" ON "ProcessStep" (uid);
COMMENT ON TABLE "ProcessStep" IS 'One node in the process graph. inputType/outputType/capabilityRef/opaEntrypoint are used selectively by kind: a GATEWAY step names opaEntrypoint (the OPA decision that selects its outgoing flow); a SERVICE step names capabilityRef and inputType/outputType; a TIMER START step carries the schedule fields Practice.processSpecRef (work.yaml) points at. Which fields apply to which kind is a Rego invariant, not encoded structurally here -- LinkML has no tagged-union/discriminated-class construct clean enough to justify one ProcessStep subclass per kind for what is otherwise one shape.';
COMMENT ON COLUMN "ProcessStep"."semanticStage" IS 'The WorkflowDeclaration-era stage this step corresponds to, where applicable.';
COMMENT ON COLUMN "ProcessStep"."capabilityRef" IS 'Required on a SERVICE step (Rego); must resolve in an ActionCapabilitySet.';
COMMENT ON COLUMN "ProcessStep".ring IS 'Must not exceed the ringCeiling of capabilityRef''s ActionCapability (Rego).';
COMMENT ON COLUMN "ProcessStep"."idempotencyKey" IS 'Required on a SERVICE step whose capability producesExternalEffect (Rego).';
COMMENT ON COLUMN "ProcessStep"."opaEntrypoint" IS 'Required on a GATEWAY step (Rego): the Rego rule the ProcessSpec compiler wires as the decision selecting this gateway''s outgoing branch.';
COMMENT ON COLUMN "ProcessStep"."terminalState" IS 'Required on END and forbidden elsewhere.';
COMMENT ON COLUMN "ProcessStep"."signalType" IS 'Required on USER and MESSAGE signals; resolves to a generated LinkML class.';
COMMENT ON COLUMN "ProcessStep"."ProcessSpecBody_id" IS 'Autocreated FK slot';
COMMENT ON COLUMN "ProcessStep"."subprocessReleaseRef_uid" IS 'The exact ProcessSpec release this SUBPROCESS step invokes (Rego required-on-SUBPROCESS check in execution.rego; must resolve, see references.rego).';

CREATE TABLE "ProcessFlow" (
	uid SERIAL NOT NULL,
	id TEXT NOT NULL,
	"from" TEXT NOT NULL,
	"to" TEXT NOT NULL,
	"branchLabel" TEXT,
	"payloadType" TEXT NOT NULL,
	"ProcessSpecBody_id" INTEGER,
	PRIMARY KEY (uid),
	FOREIGN KEY("ProcessSpecBody_id") REFERENCES "ProcessSpecBody" (id)
