COMMENT ON TABLE "WorkerSubstrateSpec" IS 'None';
COMMENT ON COLUMN "WorkerSubstrateSpec"."homeState" IS 'A mounted CLI home carries native connectors, consent history and trusted folders; isolated per-invocation state removes that duplicated authority.';
COMMENT ON COLUMN "WorkerSubstrateSpec"."nativeToolAuthority" IS 'CLI-native connectors and MCP servers are disabled so the fact is reviewable rather than hidden in an image. Unaffected by AGENTS.md''s development-agent MCP directives -- those govern a human''s own terminal session, not a dispatched worker.';
COMMENT ON COLUMN "WorkerSubstrateSpec"."ambientToolAuthority" IS 'No CLI home, image, plugin, repository file, or provider default silently grants tool access.';
COMMENT ON COLUMN "WorkerSubstrateSpec"."projectedToolAuthority" IS 'Tool capabilities are dynamically projected by the Jumo capability gateway via an invocation-scoped Streamable HTTP MCP endpoint based on explicit InvocationCapabilityGrants.';
COMMENT ON COLUMN "WorkerSubstrateSpec"."usageContext" IS 'Licensing and entitlement fact only. Not a security boundary and not a sphere.';
COMMENT ON COLUMN "WorkerSubstrateSpec"."accountUse" IS 'Which ProviderAccount use context this substrate is authorized to consume, explicit so a declared substrate never silently upgrades from holder-operated to Jumo-managed use.';
COMMENT ON COLUMN "WorkerSubstrateSpec"."executionMachineRef_uid" IS 'Durable execution machine selected for this CLI substrate; an ExecutionCellLease remains invocation-scoped.';

