CREATE TABLE "OfferingSpec" (
	id SERIAL NOT NULL,
	"apiVersion" TEXT NOT NULL,
	kind TEXT NOT NULL,
	metadata_uid INTEGER NOT NULL,
	spec_id INTEGER NOT NULL,
	PRIMARY KEY (id),
	FOREIGN KEY(metadata_uid) REFERENCES "Metadata" (uid),
	FOREIGN KEY(spec_id) REFERENCES "OfferingSpecBody" (id)
);
CREATE INDEX "ix_OfferingSpec_id" ON "OfferingSpec" (id);
COMMENT ON TABLE "OfferingSpec" IS 'Hypothesis-level managed-service offer for a client-owned Solo deployment. Records the commercial assumption separately from the durable control-plane decisions that will survive or outlive the experiment. Renamed from ManagedServiceOffer: the vehicle for offering packaging. Numeric const values in the source schema (fixed prices, fixed durations) are kept as plain typed fields with an ifabsent default carrying the source''s pinned value, rather than encoded as JSON-Schema-style constants LinkML has no direct equivalent for -- several of these are expected to become genuinely configurable, so a plain field is the more honest fidelity choice here.';

